using HelpDeskPro.Api.Data; using HelpDeskPro.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HelpDeskPro.Api.Controllers; [ApiController][Route("api/departments")][Authorize]
public class DepartmentsController:ControllerBase { private readonly AppDbContext db; public DepartmentsController(AppDbContext db){this.db=db;} int GetUserId()=>int.Parse(User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value); [HttpGet] public async Task<IActionResult> Get()=>Ok(await db.Departments.OrderBy(x=>x.Name).Select(x=>new{x.Id,x.Name,Users=x.Users.Count,Tickets=x.Tickets.Count}).ToListAsync());
[HttpGet("{id}")] public async Task<IActionResult> Details(int id){var d=await db.Departments.Include(x=>x.Users).Include(x=>x.Tickets).ThenInclude(t=>t.CreatedBy).Include(x=>x.Tickets).ThenInclude(t=>t.AssignedTo).FirstOrDefaultAsync(x=>x.Id==id);if(d==null)return NotFound();var tickets=d.Tickets.OrderByDescending(t=>t.CreatedAt).Select(t=>new{t.Id,t.Title,Status=t.Status.ToString(),Priority=t.Priority.ToString(),t.CreatedAt,t.UpdatedAt,t.SlaDueAt,Overdue=t.SlaDueAt<DateTime.UtcNow&&t.Status!=TicketStatus.Resolved&&t.Status!=TicketStatus.Closed,CreatedBy=t.CreatedBy.FullName,AssignedTo=t.AssignedTo==null?null:t.AssignedTo.FullName}).ToList();var users=d.Users.OrderBy(u=>u.FullName).Select(u=>new{u.Id,u.FullName,u.Email,Role=u.Role.ToString(),u.IsActive,u.CreatedAt}).ToList();return Ok(new{d.Id,d.Name,Users=users,Tickets=tickets,Stats=new{TotalUsers=users.Count,TotalTickets=tickets.Count,OpenTickets=tickets.Count(t=>t.Status=="Open"),InProgressTickets=tickets.Count(t=>t.Status=="InProgress"),PendingTickets=tickets.Count(t=>t.Status=="Pending"),ResolvedTickets=tickets.Count(t=>t.Status=="Resolved"),ClosedTickets=tickets.Count(t=>t.Status=="Closed"),OverdueTickets=tickets.Count(t=>t.Overdue)}});} [Authorize(Roles="Admin")][HttpPost] public async Task<IActionResult> Add(Department d){db.Departments.Add(d);await db.SaveChangesAsync();db.ActivityLogs.Add(new ActivityLog{Action=$"Created department: {d.Name}",Entity="Department",EntityId=d.Id,UserId=GetUserId()});await db.SaveChangesAsync();return Ok(d);} [Authorize(Roles="Admin")][HttpPut("{id}")] public async Task<IActionResult> Edit(int id,Department d){var x=await db.Departments.FindAsync(id);if(x==null)return NotFound();x.Name=d.Name;await db.SaveChangesAsync();db.ActivityLogs.Add(new ActivityLog{Action=$"Updated department: {x.Name}",Entity="Department",EntityId=x.Id,UserId=GetUserId()});await db.SaveChangesAsync();return Ok(x);} [Authorize(Roles="Admin")][HttpDelete("{id}")] public async Task<IActionResult> Delete(int id){var x=await db.Departments.FindAsync(id);if(x==null)return NotFound();db.Departments.Remove(x);await db.SaveChangesAsync();db.ActivityLogs.Add(new ActivityLog{Action=$"Deleted department: {x.Name}",Entity="Department",EntityId=id,UserId=GetUserId()});await db.SaveChangesAsync();return NoContent();} }
